insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-277', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Marble chips dissolve in acid more slowly than an equal mass of marble powder because the chips have', '["a smaller surface area available for collision with H$^+$","a different chemical formula","zero activation energy","a larger $E^\\circ$ as a galvanic anode"]'::jsonb, 0, 'The heterogeneous rate is surface-limited. Powdering increases the area and therefore the observed rate.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'rate-factors') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
