insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-281', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'According to collision theory, a chemically effective encounter must supply at least the', '["threshold (activation) energy","lattice energy of a salt","Faraday equivalent of the product","standard EMF of a Daniell cell"]'::jsonb, 0, 'Only collisions whose relative kinetic energy exceeds $E_a$ can cross the barrier into products.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'collision-qual') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
