insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-282', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Besides enough energy, colliding molecules must also have a suitable', '["orientation of the reactive parts toward each other","nuclear spin of every proton","colour in the visible spectrum","negative activation energy"]'::jsonb, 0, 'A steric (orientation) requirement means that a sideways or backside-wrong hit wastes the energy of an otherwise hot collision.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'collision-qual') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
